//
// the launch flag is no longer hard-coded in this bundle -- moved it out.
// it now lives at:  /assets/vip/launch.flag
// it's scrambled -> CyberChef recipe:  From Base64  then  XOR { key: 17 (0x17), Decimal }
const VIP_FLAG_URL = "/assets/vip/launch.flag";

const BASE_RATES = { emerald: 1, diamond: 9, gold_ingot: 3, wheat: 0.25 };

function priceFor(item, qty) {
  const rate = BASE_RATES[item] || 0;
  return Math.max(1, Math.round(rate * qty));
}

function renderStall(items) {
  return items
    .map((it) => it.name + " x" + it.qty + " = " + priceFor(it.id, it.qty) + "em")
    .join("\n");
}

window.TradingHub = { priceFor, renderStall };
